var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<TicketsDb>(o => o.UseSqlite("Data Source=lighthouse.db"));
var app = builder.Build();

using (var scope = app.Services.CreateScope())
    scope.ServiceProvider.GetRequiredService<TicketsDb>().Database.EnsureCreated();

// Seeding endpoints for the tests (already in production).
app.MapPost("/events", async (Event e, TicketsDb db, CancellationToken ct) =>
{
    db.Events.Add(e);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/events/{e.Id}", new { e.Id });
});
app.MapPost("/bookings", async (Booking b, TicketsDb db, CancellationToken ct) =>
{
    b.Version = 1;
    db.Bookings.Add(b);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/bookings/{b.Id}", new { b.Id, b.Version });
});
app.MapGet("/events", (TicketsDb db) =>
    db.Events.OrderBy(e => e.StartsAt).Select(e => new { e.Id, e.Name, e.StartsAt }).ToList());

app.MapGet("/events/{id:int}", (int id, TicketsDb db) =>
{
    var e = db.Events.Where(x => x.Id == id).Select(x => new { x.Id, x.Name, x.StartsAt }).FirstOrDefault();
    return e is null ? Results.NotFound() : Results.Ok(e);
});

app.Run();

record BookingRow(int Id, string Customer, string EventName);
record BookingEdit(string Note, int Version);

class Event
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string StartsAt { get; set; } = "";
    public List<Booking> Bookings { get; set; } = [];
}

class Booking
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public Event? Event { get; set; }
    public string Customer { get; set; } = "";
    public string Note { get; set; } = "";
    [ConcurrencyCheck] public int Version { get; set; }
}

class TicketsDb(DbContextOptions<TicketsDb> options) : DbContext(options)
{
    public DbSet<Event> Events => Set<Event>();
    public DbSet<Booking> Bookings => Set<Booking>();
}

