var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<TicketsDb>(o => o.UseSqlite("Data Source=lighthouse.db"));
var app = builder.Build();

using (var scope = app.Services.CreateScope())
    scope.ServiceProvider.GetRequiredService<TicketsDb>().Database.EnsureCreated();

// Seeding endpoints for the tests (already in production).
app.MapPost("/events", async (Event e, TicketsDb db, CancellationToken ct) =>
{
    db.Events.Add(e);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/events/{e.Id}", new { e.Id });
});
app.MapPost("/bookings", async (Booking b, TicketsDb db, CancellationToken ct) =>
{
    b.Version = 1;
    db.Bookings.Add(b);
    await db.SaveChangesAsync(ct);
    return Results.Created($"/bookings/{b.Id}", new { b.Id, b.Version });
});
app.MapPut("/bookings/{id:int}", async (int id, BookingEdit edit, TicketsDb db, CancellationToken ct) =>
{
    var booking = await db.Bookings.FirstOrDefaultAsync(b => b.Id == id, ct);
    if (booking is null) return Results.NotFound();
    db.Entry(booking).Property(b => b.Version).OriginalValue = edit.Version;
    booking.Note = edit.Note;
    booking.Version = edit.Version + 1;
    try
    {
        await db.SaveChangesAsync(ct);
        return Results.Ok(new { booking.Id, booking.Note, booking.Version });
    }
    catch (DbUpdateConcurrencyException ex)
    {
        var current = await ex.Entries[0].GetDatabaseValuesAsync(ct);
        return Results.Conflict(new { error = "changed by someone else", currentVersion = current?.GetValue<int>("Version") });
    }
});

app.Run();

